css:
.main-content{
    font-family: 'Times New Roman',serif; 
    font-size: 14px; 
    line-height: 1.6; 
    color: black;
    width: 100%;
}

.table-content {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
    color: black;
    font-family: 'Times New Roman';
}
.table-content th, .table-content td {
    border: 1px solid #444;
    padding: 6px;
    text-align: left;
}
.table-content th {
    background-color: #f2f2f2;
    font-weight: bold;
}

.text-left{
    text-align: left;
}

.text-right{
    text-align: right;
}

.text-center{
    text-align: center;
}

@media print {
    .page-break { display: none; }
    body { margin: 0; }
    table { page-break-inside: auto !important; }
    tr { page-break-inside: avoid !important; }
}
